/****************************************************************************
 * Name: nxsem_trywait_slow
 *
 * Description:
 *   This function locks the specified semaphore in slow mode.
 *
 * Input Parameters:
 *   sem - the semaphore descriptor
 *
 * Returned Value:
 *
 *     EINVAL - Invalid attempt to get the semaphore
 *     EAGAIN - The semaphore is not available.
 *
 * Assumptions:
 *
 ****************************************************************************/

int nxsem_trywait_slow(FAR sem_t *sem)
{
  irqstate_t flags;
  int ret = OK;
  bool mutex = NXSEM_IS_MUTEX(sem);
  FAR atomic_t *val = mutex ? NXSEM_MHOLDER(sem) : NXSEM_COUNT(sem);
  int32_t old;
  int32_t new;

  /* The following operations must be performed with interrupts disabled
   * because sem_post() may be called from an interrupt handler.
   */

  flags = enter_critical_section();

  /* If the semaphore is available, give it to the requesting task */

  old = atomic_read(val);
  do
    {
      if (mutex)
        {
          if (NXSEM_MACQUIRED(old))
            {
              ret = -EAGAIN;
              break;
            }

          new = nxsched_gettid();
        }
      else
        {
          if (old <= 0)
            {
              ret = -EAGAIN;
              break;
            }

          new = old - 1;
        }
    }
  while (!atomic_try_cmpxchg_acquire(val, &old, new));

  if (ret != -EAGAIN)
    {
      /* It is, let the task take the semaphore */

  #ifdef CONFIG_PRIORITY_PROTECT
      ret = nxsem_protect_wait(sem);
      if (ret < 0)
        {
          if (mutex)
            {
              atomic_set(NXSEM_MHOLDER(sem), NXSEM_NO_MHOLDER);
            }
          else
            {
              atomic_add(NXSEM_COUNT(sem), 1);
            }
        }
      else
  #endif
        {
          if (!mutex)
            {
              nxsem_add_holder(sem);
            }
        }
    }

  /* Interrupts may now be enabled. */

  leave_critical_section(flags);
  return ret;
}

