{
  struct timespec now;
  struct timespec deadline;
  int wait_times;

  wait_times = 0;
  if (signest_catchable(sig))
    {
      wait_times++;
    }

  if (signest_catchable(sig + 1))
    {
      wait_times++;
    }

  clock_gettime(CLOCK_MONOTONIC, &deadline);
  deadline.tv_sec += 2;

  while (wait_times > 0)
    {
      if (sem_trywait(&g_sem_signal_finish) == OK)
        {
          wait_times--;
          continue;
        }

      if (errno != EAGAIN)
        {
          printf("signest_test: sem_trywait failed sig=%d/%d errno=%d\n",
