void weak_function up_timer_getmask(FAR clock_t *mask)
{
  uint32_t maxticks;

  TIMER_TICK_MAXTIMEOUT(g_timer.lower, &maxticks);

  *mask = 0;
  while (1)
    {
      clock_t next = (*mask << 1) | 1;
      if (next > maxticks)
        {
          break;
        }

      *mask = next;
    }
}

