+  if (info->si_code != SI_TIMER)
     {
-      printf("timer_expiration: ERROR si_code=%d, expected SI_TIMER=%d\n",
-             info->si_code, SI_TIMER);
       ASSERT(false);
     }

-  /* Check ucontext_t */
-
-  printf("timer_expiration: ucontext=%p\n" , ucontext);
