/****************************************************************************
 * Name: wd_gettime
 *
 * Description:
 *   This function returns the time remaining before the specified watchdog
 *   timer expires.
 *
 * Input Parameters:
 *   wdog - watchdog ID
 *
 * Returned Value:
 *   The time in system ticks remaining until the watchdog time expires.
 *   Zero means either that wdog is not valid or that the wdog has already
 *   expired.
 *
 ****************************************************************************/

clock_t wd_gettime(FAR struct wdog_s *wdog)
{
  sclock_t delay = 0;

  if (wdog && WDOG_ISACTIVE(wdog))
    {
      delay = (sclock_t)(wdog->expired - clock_systime_ticks());
      delay = delay < 0 ? 0 : delay;
    }

  return (clock_t)delay;
}
