            }
          else
            {
              printf("timer_test: ERROR sem_wait failed, errno=%d\n", error);
              ASSERT(false);
            }
        }
      else
        {
          printf("timer_test: ERROR awakened with no error!\n");
          ASSERT(false);
        }

      printf("timer_test: g_nsigreceived=%d\n", g_nsigreceived);
    }

