Get-ChildItem arch/arm/src/bk7258 -Recurse -File -Include *.c,*.h | ForEach-Object {
  $text = [IO.File]::ReadAllText($_.FullName).Replace("`r`n", "`n")

  if ($text -notmatch '(?m)^ \* Included Files$') {
    $match = [regex]::Match($text, '(?m)^#include\b')
    if ($match.Success) {
      $section = $sectionTemplate -f 'Included Files'
      $text = $text.Insert($match.Index, $section)
    }
  }

  if ($text -notmatch '(?m)^ \* Pre-processor Definitions$') {
    $matches = [regex]::Matches($text, '(?m)^#define\s+([A-Za-z_][A-Za-z0-9_]*)')
    $target = $null
    foreach ($match in $matches) {
      $name = $match.Groups[1].Value
      $prefix = $text.Substring(0, $match.Index)
      $isHeaderGuard = $_.Extension -eq '.h' -and
        $prefix -match '(?m)^#ifndef\s+' + [regex]::Escape($name) + '\s*$'
      if (-not $isHeaderGuard) {
        $target = $match
        break
      }
    }

    if ($null -ne $target) {
      $section = $sectionTemplate -f 'Pre-processor Definitions'
      $text = $text.Insert($target.Index, $section)
    }
  }

  [IO.File]::WriteAllText($_.FullName, $text, [Text.UTF8Encoding]::new($false))
}
