+)
+
+$entries = @{}
+$pattern = '^.*?/arch/arm/src/bk7258/(?<file>.*?):(?<line>\d+):(?<col>\d+): error: (?<message>.*)$'
+
+foreach ($record in Select-String -LiteralPath $LogPath -Pattern 'error:')
+{
+  if ($record.Line -match $pattern)
+    {
+      $key = "$($matches.file):$($matches.line)"
+      if (-not $entries.ContainsKey($key))
+        {
+          $entries[$key] = [ordered]@{
+            File = $matches.file
+            Line = [int]$matches.line
+            Messages = @()
+          }
+        }
+
+      $entries[$key].Messages += $matches.message
+    }
+}
+
+$byFile = $entries.Values | Group-Object File
+foreach ($group in $byFile)
+{
+  $path = Join-Path $RepoRoot ('arch/arm/src/bk7258/' + $group.Name)
+  $lines = [System.Collections.Generic.List[string]]::new()
+  $lines.AddRange([string[]][System.IO.File]::ReadAllLines($path))
+
+  foreach ($entry in ($group.Group | Sort-Object Line -Descending))
+    {
+      $index = $entry.Line - 1
+      $messages = $entry.Messages
+
+      if ($messages -contains 'Missing whitespace after semicolon')
+        {
+          $lines[$index] = $lines[$index].Replace('for (;;)', 'for (; ; )')
+        }
+
+      if ($messages -contains 'Block comment terminator must be on a separate line')
+        {
+          $line = $lines[$index]
+          if ($line -match '^(?<indent>\s*)\*(?<body>.*) \*/\s*$')
+            {
+              $lines[$index] = "$($matches.indent)*$($matches.body)"
+              $lines.Insert($index + 1, "$($matches.indent)*/")
+            }
+          elseif ($line -match '^(?<indent>\s*)/\*(?<body>.*) \*/\s*$')
+            {
+              $lines[$index] = "$($matches.indent)/*$($matches.body)"
+              $lines.Insert($index + 1, "$($matches.indent) */")
+            }
+        }
+
+      if ($messages -contains 'Missing blank line after comment')
+        {
+          $endIndex = $index
+          if ($endIndex + 1 -lt $lines.Count -and
+              $lines[$endIndex + 1].Trim() -eq '*/')
+            {
+              $endIndex++
+            }
+
+          if ($endIndex + 1 -lt $lines.Count -and
+              $lines[$endIndex + 1].Length -ne 0)
+            {
+              $lines.Insert($endIndex + 1, '')
+            }
+        }
+
+      if ($messages -contains 'Missing blank line before comment found')
+        {
+          if ($index -gt 0 -and $lines[$index - 1].Length -ne 0)
+            {
+              $lines.Insert($index, '')
+            }
+        }
+
+      if ($messages -contains 'Right brace must be followed by a blank line')
+        {
+          if ($index + 1 -lt $lines.Count -and
+              $lines[$index + 1].Length -ne 0)
+            {
+              $lines.Insert($index + 1, '')
+            }
+        }
+    }
+
+  [System.IO.File]::WriteAllLines(
+    $path,
+    $lines,
+    [System.Text.UTF8Encoding]::new($false))
+}
*** End Patch";
