/****************************************************************************
 * Name: cmtestfillfilewithfd
 ****************************************************************************/

static int cmtestfillfilewithfd(int fd, char pattern, size_t bs,
                                size_t bcount)
{
  size_t i;
  char *buf;

  /* Filling a memory buffer with provided pattern */

  buf = (char *)malloc(bs);
  if (buf == NULL)
      return -1;

  for (i = 0; i < bs; i++)
    buf[i] = pattern;

  /* Filling the file */

  for (i = 0; i < bcount; i++)
    {
      if (write(fd, buf, bs) != (ssize_t)bs)
        {
          free(buf);
          return -1;
        }
    }

  free(buf);

  return 0;
}

